@spec tv_fx_region_spec  src=tests/specs/tv_fx_region_spec.lua  loc=1319  cases=67
@exercises dataStore (h.ds), trackerManager (h.tm), midiManager (h.fm), trackerView (h.vm), editCursor (h.ec), commandManager (h.cmgr), clipboard (h.clipboard)
@surface   ds:assign, tm:rebuild, ds:get, tm:addEvent, tm:flush, fm:dump, vm:setGridSize, vm:ppqToRow, ec:setPos, vm:fxHostForEdit, vm:noteFx, vm:setNoteFx, vm:removeFxStage, vm:addFxStage, vm:setFxField, ec:setSelection, vm:rowToPPQ, vm:fxHostAtCursor, cmgr:invoke, tm:getChannel, vm:editEvent, tm:subscribe, ec:row, ec:extendTo, clipboard:collect, vm:ghostOverlay
@harness   mk{seed.ccs}

# Intent
  Track B (note macros v2): the fx-region column + Super-X addressing. A region
  renders as a tailed kind-badge in a per-channel fx column, and the v1 note-FX
  editor addresses it by uuid. see design/note-macros-v2.md § Authoring and editing the fx

# Helpers
  @fn injectRegion(h, over)  @ 24-29
  @fn fxColFor(h, chan)  @ 31-35
  @fn region(h, uuid)  @ 37-41
  @fn noteColIdx(h, chan, lane)  @ 43-47
  @fn ctsColIdx(h, chan, type, cc)  @ 49-53
  @fn addNote(h)  @ 55-59
  @fn authoredUuid(h)  @ 61-63
  @fn authoredPitches(h)  @ 67-74
      -- Pitches still sounding on the take (non-derived). Empty once a replace region has
      -- parked the covered chord off-take.

# Cases
  @case 'a region materialises a per-channel fx column with a badge + tail'  [harness]  @ 81-93
  @case 'a chain stacks its glyphs down the region rows in series order'  [harness]  @ 97-110
  @case 'a bypassed stage carries its flag down the stack'  [harness]  @ 114-124
  @case 'a chain longer than the region clips at the last row and marks it'  [harness]  @ 128-138
  @case 'a one-row region gives the clip mark the badge row'  [harness]  @ 142-150
  @case 'no region -> no fx column'  [harness]  @ 154-160
  @case 'an empty-fx region renders no column (it is an inert husk)'  [harness]  @ 164-170
  @case 'two overlapping regions pack into separate fx columns, each addressable'  [harness]  @ 176-204
  @case 'two disjoint regions share one fx column (packed into lane 1)'  [harness]  @ 208-220
  @case 'replace region: a parked note still renders in its note column'  [harness]  @ 226-238
  @case 'replace region: a parked cc still renders in its cc column'  [harness]  @ 242-265
  @case 'noteFx resolves a region uuid to its fx list'  [harness]  @ 271-276
  @case 'setNoteFx writes a region fx list back to ds'  [harness]  @ 280-286
  @case 'setNoteFx REMOVE deletes the region (a region is its fx)'  [harness]  @ 290-296
  @case 'region fx: deselecting the last kind keeps a husk the editor can repopulate'  [harness]  @ 300-310
  @case 'setFxField edits one region fx field, leaving the region'  [harness]  @ 314-320
  @case 'fxHostForEdit: caret on an fx cell returns the region uuid'  [harness]  @ 326-334
  @case 'fxHostForEdit: a selection mints a replace region over its span'  [harness]  @ 338-352
  @case 'fxHostAtCursor: a selection does not mint -- cursor movement has no side effect'  [harness]  @ 356-364
  @case 'fxHostAtCursor: caret anywhere in an fx region returns its uuid, nil past the tail'  [harness]  @ 368-381
  @case 'fxHostForEdit: off a note with no selection is nil; on a note, its uuid (v1)'  [harness]  @ 385-395
  @case 'parked note: a pitch nudge edits the off-take stash and re-renders, still parked'  [harness]  @ 401-415
  @case 'parked note: delete removes it from the stash and does not restore it when the window moves off'  [harness]  @ 419-430
  @case 'parked add: typing a note into a replace window stashes a logical spec, off the take'  [harness]  @ 434-448
  @case 'parked move-out: nudging a parked note past the window end restores it to the take'  [harness]  @ 452-465
  @case 'parked cc: a value nudge edits the off-take cc stash; delete removes it'  [harness]  @ 469-501
  @case 'parked pb: a value nudge edits the off-take pb stash; delete removes it'  [harness]  @ 505-541
  @case 'multi-select spanning a parked note and a take note: both edit under one rebuild'  [harness]  @ 545-566
  @case 'fx noteOff truncates the region tail to the cursor row'  [harness]  @ 572-584
  @case 'fx noteOff finds the right region in its lane when cells are in storage, not ppq, order'  [harness]  @ 588-602
  @case 'fx noteOff past the region tail grows it to the cursor row'  [harness]  @ 606-615
  @case 'fx noteOff on the onset row is a no-op (deletion is the delete verb, not noteOff)'  [harness]  @ 619-630
  @case 'fx noteOff on the window end row re-opens it to the pattern length'  [harness]  @ 634-644
  @case 'fx growNote / shrinkNote resize the region from its end'  [harness]  @ 648-659
  @case 'fx nudgeForward shifts the whole window and the caret follows'  [harness]  @ 663-675
  @case 'fx nudge keeps the moved region in its lane; the newly-overlapped sibling displaces right'  [harness]  @ 679-701
  @case 'fx nudge of an already-overlapping region keeps its own higher lane (no reorder)'  [harness]  @ 705-724
  @case 'fx nudge that makes an overlap disjoint tracks the caret across the column merge'  [harness]  @ 728-748
  @case 'fx window edit on a disjoint region does not churn storage order'  [harness]  @ 752-768
  @case 'fx nudgeBack refuses at the top grid edge (window unchanged)'  [harness]  @ 772-783
  @case 'fx eventShiftLeft swaps the region one lane left, flipping storage precedence'  [harness]  @ 789-813
  @case 'fx eventShiftRight swaps the region one lane right (the inverse move)'  [harness]  @ 817-832
  @case 'fx eventShift is a no-op at the grid edge (lone region, nothing beside it)'  [harness]  @ 836-848
  @case 'fx eventShift no-ops when the adjacent lane is empty at the cursor row'  [harness]  @ 852-867
  @case 'parked note: noteOff shortens its tail in the stash, stays parked'  [harness]  @ 873-886
  @case 'parked note: a time nudge within the window retimes the stash, stays parked'  [harness]  @ 890-903
  @case 'fx copy captures a region by onset; the whole window rides, tail spilling past the band'  [harness]  @ 909-927
  @case 'fx copy skips a region that only passes through the band (onset above it)'  [harness]  @ 931-940
  @case 'fx copy + paste stacks a duplicate region at the cursor row, original intact'  [harness]  @ 944-964
  @case 'fx delete removes the region under the caret'  [harness]  @ 968-977
  @case 'fx deleteSel drops every region the rectangle catches (onset in band), sparing the rest'  [harness]  @ 981-998
  @case 'fx freeze promotes the region output to authored notes and drops the region'  [harness]  @ 1004-1016
  @case 'fx freeze converts an fx-carrying note at the caret'  [harness]  @ 1020-1032
  @case 'fx freeze declines on a plain note (no chain to freeze)'  [harness]  @ 1036-1046
  @case 'fx freeze: a refused freeze opens no undo block; an eligible one opens exactly one'  [harness]  @ 1053-1090
  @case 'ghostOverlay: no host under the caret returns nil, before any window query'  [harness]  @ 1096-1105
  @case 'ghostOverlay: a host lights its derived onsets on the lane column, with pitch and vel'  [harness]  @ 1109-1134
  @case 'ghostOverlay: a host whose onsets lie outside the window answers empty, not nil'  [harness]  @ 1138-1150
  @case 'ghostOverlay: a row carrying a real cell still reports its ghost -- precedence is the draw arm\'s'  [harness]  @ 1154-1166
  @case 'ghostOverlay: the window is the viewport -- onsets below it are absent'  [harness]  @ 1170-1185
  @case 'ghostOverlay: a polyphonic chain\'s ghosts land on the provisional lane columns'  [harness]  @ 1190-1205
  @case 'ghostOverlay: a pb chain lights its curve on the column it claimed'  [harness]  @ 1211-1229
  @case 'ghostOverlay: only the claimed target lights -- an authored cc beside it stays dark'  [harness]  @ 1233-1245
  @case 'ghostOverlay: no host, no curve'  [harness]  @ 1249-1258
  @case 'ghostOverlay: a region host suppresses the parked chord it replaced, cells intact'  [harness]  @ 1264-1283
  @case 'ghostOverlay: the host\'s own parked cell stays visible'  [harness]  @ 1287-1304
  @case 'ghostOverlay: nothing on the take is ever suppressed'  [harness]  @ 1308-1317

